def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count replacements having at least k reducible contiguous substrings.

    Equal pairs and ABC triples can be deleted in any positions. Consequently
    a string is reducible exactly when its three character counts have the same
    parity. Encoding A, B, C by 1, 2, 3 makes this equivalent to zero XOR.

    Track the frequencies of the four prefix XOR values and the current XOR.
    Equal prefix XOR pairs count exactly the good substrings.
    """
    mod = 998244353
    if k == 0:
        return pow(3, s.count('?'), mod)

    # Consecutive prefix XORs differ. The most equal pairs possible are
    # obtained by alternating between two values.
    if k > n * n // 4:
        return 0

    # A state stores counts of prefix values 0, 1, 2, followed by the
    # current prefix XOR. The count of value 3 follows from the length.
    dp = {(1, 0, 0, 0): 1}
    codes = {'A': (1,), 'B': (2,), 'C': (3,), '?': (1, 2, 3)}
    for char in s:
        next_dp = {}
        for (a, b, c, last), ways in dp.items():
            for code in codes[char]:
                current = last ^ code
                if current == 0:
                    state = (a + 1, b, c, current)
                elif current == 1:
                    state = (a, b + 1, c, current)
                elif current == 2:
                    state = (a, b, c + 1, current)
                else:
                    state = (a, b, c, current)
                next_dp[state] = (next_dp.get(state, 0) + ways) % mod
        dp = next_dp

    answer = 0
    for (a, b, c, last), ways in dp.items():
        d = n + 1 - a - b - c
        good = (a * (a - 1) + b * (b - 1) +
                c * (c - 1) + d * (d - 1)) // 2
        if good >= k:
            answer = (answer + ways) % mod
    return answer

