def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count replacements by 1, 2, 3 with unequal edge-adjacent cells.

    H and W are positive and H * W <= 200. Fixed digits are preserved.
    Return the number of valid configurations modulo 998244353.
    """
    mod = 998244353
    # The frontier width is at most sqrt(200), regardless of orientation.
    if W > H:
        grid = [''.join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # A fixed equal pair makes every possible completion invalid.
    for r in range(H):
        for c in range(W):
            value = grid[r][c]
            if value != '?':
                if c and grid[r][c - 1] == value:
                    return 0
                if r and grid[r - 1][c] == value:
                    return 0

    # Each two-bit slot holds one color; zero denotes an unfilled cell.
    # Before a cell is processed the oldest slot is its upper neighbor,
    # and the newest slot is its left neighbor (except at row boundaries).
    high_shift = 2 * (W - 1)
    keep_mask = (1 << high_shift) - 1
    dp = {0: 1}
    for row in grid:
        for c, value in enumerate(row):
            colors = (1, 2, 3) if value == '?' else (int(value),)
            following = {}
            for state, ways in dp.items():
                above = state >> high_shift
                left = (state & 3) if c else 0
                prefix = (state & keep_mask) << 2
                for color in colors:
                    if color != above and color != left:
                        new_state = prefix | color
                        following[new_state] = (following.get(new_state, 0) + ways) % mod
            dp = following
            if not dp:
                return 0
    return sum(dp.values()) % mod

