def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    """Return the sum of products of good sequences modulo 998244353.

    For each prime, neighboring exponents differ by exactly its exponent in
    a[i] (with either sign). The minimum exponent must be zero. Choices for
    distinct primes are independent, so their weighted sums multiply.
    """
    mod = 998244353
    factors = {}
    for index, value in enumerate(a):
        divisor = 2
        while divisor * divisor <= value:
            if value % divisor == 0:
                exponent = 0
                while value % divisor == 0:
                    value //= divisor
                    exponent += 1
                if divisor not in factors:
                    factors[divisor] = [0] * (n - 1)
                factors[divisor][index] = exponent
            divisor += 1
        if value > 1:
            if value not in factors:
                factors[value] = [0] * (n - 1)
            factors[value][index] = 1

    answer = 1
    for prime, differences in factors.items():
        total = sum(differences)
        powers = [1] * (total + 1)
        for exponent in range(1, total + 1):
            powers[exponent] = powers[exponent - 1] * prime % mod

        # dp[h] sums products of normalized prefixes ending at exponent h.
        dp = [1]
        for length, difference in enumerate(differences, 1):
            if difference == 0:
                dp = [
                    weight * powers[height] % mod
                    for height, weight in enumerate(dp)
                ]
                continue

            next_dp = [0] * (len(dp) + difference)
            # If a downward step sets a new minimum, all 'length' old
            # exponents increase by difference - height.
            shift_base = pow(prime, length, mod)
            shifts = [1] * (difference + 1)
            for delta in range(1, difference + 1):
                shifts[delta] = shifts[delta - 1] * shift_base % mod

            for height, weight in enumerate(dp):
                if weight == 0:
                    continue
                up = height + difference
                next_dp[up] = (next_dp[up] + weight * powers[up]) % mod
                if height >= difference:
                    down = height - difference
                    next_dp[down] = (
                        next_dp[down] + weight * powers[down]
                    ) % mod
                else:
                    next_dp[0] = (
                        next_dp[0] + weight * shifts[difference - height]
                    ) % mod
            dp = next_dp

        answer = answer * (sum(dp) % mod) % mod
    return answer

