from typing import List, Tuple


def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    """Return the largest subtree whose degrees are 1 or 4, with a degree-4 vertex.

    An alkane must contain at least one degree-4 vertex. Return -1 if none
    exists. Vertices are numbered 1 through n; n is at most 200,000.
    """
    adj = [[] for _ in range(n)]
    for a, b in edges:
        a -= 1
        b -= 1
        adj[a].append(b)
        adj[b].append(a)

    parent = [-1] * n
    order = [0]
    for v in order:
        for w in adj[v]:
            if w != parent[v]:
                parent[w] = v
                order.append(w)

    # branch[v] includes v and assumes its edge to its parent is selected.
    # Then v is either a leaf, or uses its three largest child branches.
    branch = [1] * n
    answer = -1
    for v in reversed(order):
        a = b = c = d = 0
        for w in adj[v]:
            if w == parent[v]:
                continue
            size = branch[w]
            if size >= a:
                a, b, c, d = size, a, b, c
            elif size >= b:
                b, c, d = size, b, c
            elif size >= c:
                c, d = size, c
            elif size > d:
                d = size
        if c:
            branch[v] = 1 + a + b + c
            # The shallowest degree-4 vertex can use its parent as a leaf.
            if parent[v] != -1:
                answer = max(answer, 2 + a + b + c)
        if d:
            # Or the shallowest selected vertex is itself degree 4.
            answer = max(answer, 1 + a + b + c + d)
    return answer
